css:
.cmpt { overflow-x: auto; }
.cmpt table { width: 100%; border-collapse: separate; border-spacing: 0; border: 1px solid color-mix(in srgb, var(--ink) 10%, transparent); border-radius: 14px; overflow: hidden; font-family: var(--font-body); }
.cmpt__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.cmpt thead th { text-align: left; padding: 14px 16px; background: var(--ink); color: #fff; font-size: 14px; font-weight: 700; }
.cmpt thead th.is-hl { background: var(--accent-dark); }
.cmpt tbody th, .cmpt td { text-align: left; padding: 14px 16px; border-bottom: 1px solid color-mix(in srgb, var(--ink) 8%, transparent); font-size: 15px; line-height: 1.55; color: color-mix(in srgb, var(--ink) 87%, var(--paper)); vertical-align: top; background: var(--card); }
.cmpt tbody tr:last-child th, .cmpt tbody tr:last-child td { border-bottom: 0; }
.cmpt tbody th { font-weight: 700; color: var(--ink); }
.cmpt tbody tr:nth-child(even) th, .cmpt tbody tr:nth-child(even) td { background: var(--paper); }
.cmpt td.is-hl, .cmpt tbody tr:nth-child(even) td.is-hl { background: var(--accent-tint); color: var(--ink); font-weight: 700; }
